from pathlib import Path
import json
from build_zhongli_full import F

def main():
 bank=json.loads((F/'actions.json').read_text())
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>钟离 · 全动作拟合对照</title><style>body{font:16px/1.7 system-ui;max-width:1500px;margin:auto;padding:20px;background:#202635;color:#e9eef5}a{color:#f6cc85}.bar{display:flex;flex-wrap:wrap;gap:12px;align-items:center}button,select{font:inherit;padding:8px;background:#303c53;color:white;border:1px solid #79849a;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}canvas{width:100%;height:auto;image-rendering:pixelated}section{border:1px solid #66708a;padding:12px}#error{color:#ffb5b5}h1{font-size:25px}@media(max-width:850px){.grid{grid-template-columns:1fr}}</style><h1>钟离 · 原图／初始拟合／优化拟合</h1><p><a href="index.html">返回全动作播放</a> · <a href="pose-report.json" download>下载逐姿台账</a></p><p>三列使用同一动作、同一世界锚点和登记倍率；不用武器外框等高。头部投影估计与浮空根仅为初步引导，不能代替逐姿解剖或用户验收。</p><div class="bar"><label>动作<select id="action"></select></label><button id="prev">上一姿</button><button id="next">下一姿</button><button id="play">播放</button><label>背景<select id="theme"><option value="#202635">深色</option><option value="#ffffff">白色</option></select></label><label><input id="mirror" type="checkbox">整舞台镜像</label><span id="phase"></span></div><p id="error" role="status"></p><div class="grid"><section><h2>源图</h2><canvas id="source" width="1000" height="450"></canvas><a id="download-source" download>下载当前源姿PNG</a></section><section><h2>初始拟合</h2><canvas id="initial" width="1000" height="450"></canvas><a id="download-initial" download>下载初始拟合PNG</a></section><section><h2>优化拟合</h2><canvas id="optimized" width="1000" height="450"></canvas><a id="download-optimized" download>下载优化拟合PNG</a></section></div><script type="application/json" id="data">DATA</script><script>
'use strict';const bank=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),cache=new Map();let index=0,playing=false,version=0,elapsed=0;
function image(file){if(!cache.has(file))cache.set(file,new Promise((ok,no)=>{const im=new Image();im.onload=()=>ok(im);im.onerror=()=>no(Error('无法载入 '+file));im.src=file}));return cache.get(file)}
async function draw(){const mine=++version,d=bank[$('action').value],i=index;try{const frames=[d.sourceFrames[i],d.initialFrames[i],d.frames[i]],loaded=await Promise.all(frames.map(f=>image(f.file)));if(mine!==version)return;for(const [j,name]of ['source','initial','optimized'].entries()){const f=frames[j],im=loaded[j],c=$(name).getContext('2d');c.fillStyle=$('theme').value;c.fillRect(0,0,1000,450);c.save();if($('mirror').checked){c.translate(1000,0);c.scale(-1,1)}c.strokeStyle='#8c8790';c.beginPath();c.moveTo(0,410);c.lineTo(1000,410);c.stroke();c.imageSmoothingEnabled=false;const y=d.sourceFrames[i].rootKind?.includes('pelvis')?255:410;c.drawImage(im,350-f.anchor[0]*f.scale,y-f.anchor[1]*f.scale,im.naturalWidth*f.scale,im.naturalHeight*f.scale);c.restore();$('download-'+name).href=f.file}$('phase').textContent=(i+1)+'/'+d.frames.length+' · '+d.phases[i];$('error').textContent=''}catch(e){$('error').textContent=String(e)}}
for(const k of Object.keys(bank)){const option=document.createElement('option');option.value=k;option.textContent=k;$('action').append(option)}
$('action').onchange=()=>{index=0;elapsed=0;draw()};$('theme').onchange=draw;$('mirror').onchange=draw;function step(delta){playing=false;$('play').textContent='播放';const n=bank[$('action').value].frames.length;index=(index+delta+n)%n;draw()}
$('prev').onclick=()=>step(-1);$('next').onclick=()=>step(1);$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'暂停':'播放'};setInterval(()=>{if(playing){elapsed+=50;const d=bank[$('action').value];if(elapsed>=d.durations[index]/60*1000*3){elapsed=0;index=(index+1)%d.frames.length;draw()}}},50);draw();
</script></html>'''.replace('DATA',json.dumps(bank,ensure_ascii=False).replace('<','\\u003c'))
 (F/'size-review.html').write_text(page)
if __name__=='__main__':main()
